import{c as r,Q as o,j as d,m as n}from"./chunks/framework.rWdQudnF.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-过程管理","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-过程管理"},"headers":[],"relativePath":"综合知识/软件工程/过程管理.md","filePath":"综合知识/软件工程/过程管理.md","lastUpdated":null}'),e={name:"综合知识/软件工程/过程管理.md"};function s(g,t,l,a,i,h){return o(),d("div",null,[...t[0]||(t[0]=[n('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 软件开发生命周期（SDLC 三阶段）</li><li>[x] 软件工程过程（PDCA）</li><li>[x] 软件系统工具分类（开发/维护/管理支持）</li><li>[x] CMM 能力成熟度模型（5 级）</li><li>[x] CMMI（阶段式/连续式）</li><li>[x] 软件过程模型对比（瀑布/原型/增量/螺旋/敏捷/RUP/喷泉/CBSD/形式化）</li><li>[x] 瀑布模型（结构化开发/需求明确）</li><li>[x] 原型模型（抛弃型/演化型）</li><li>[x] 增量模型（核心模块优先）</li><li>[x] 螺旋模型（风险驱动/大型高风险）</li><li>[x] 敏捷方法（XP/水晶/Scrum/FDD）</li><li>[x] 统一过程模型 RUP（4+1 视图/4 阶段/9 核心工作流）</li><li>[x] 净室软件工程</li><li>[x] 开发模型补充（瀑布6阶段/V模型/RAD流程/迭代vs增量/原型目的）</li><li>[x] 敏捷方法补充（DSDM/开源方法/FDD首席程序员）</li><li>[x] CMMI 补充（体系文件四层/四知识体系/各级别辨析）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="〇、软件工程核心概念" tabindex="-1">〇、软件工程核心概念 <a class="header-anchor" href="#〇、软件工程核心概念" aria-label="Permalink to &quot;〇、软件工程核心概念&quot;">​</a></h3><blockquote><p>🎯 一句话结论：软件工程的核心思想是将<strong>工程化方法</strong>应用于软件开发、运行和维护全过程。</p></blockquote><p><strong>软件过程基本活动（4项）：</strong> 软件描述 → 软件开发 → 软件有效性验证 → 软件进化 <strong>软件生存周期模型：</strong> 为各项任务提供规程约束的工作模型，不等于软件开发模型本身。</p><hr><h3 id="一、软件开发生命周期-sdlc" tabindex="-1">一、软件开发生命周期（SDLC） <a class="header-anchor" href="#一、软件开发生命周期-sdlc" aria-label="Permalink to &quot;一、软件开发生命周期（SDLC）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时期</th><th>内容</th><th>具体步骤</th></tr></thead><tbody><tr><td><strong>软件定义时期</strong></td><td>确定总目标</td><td>问题定义、可行性研究、需求分析</td></tr><tr><td><strong>软件开发时期</strong></td><td>设计与实现</td><td>概要设计、详细设计、编码、测试</td></tr><tr><td><strong>软件运行和维护</strong></td><td>交付使用并持续维护</td><td>维护、更新</td></tr></tbody></table><p><strong>软件设计四大活动：</strong> 数据设计 → 架构设计 → 人机界面设计 → 过程设计。</p><hr><h3 id="二、软件工程过程-pdca" tabindex="-1">二、软件工程过程（PDCA） <a class="header-anchor" href="#二、软件工程过程-pdca" aria-label="Permalink to &quot;二、软件工程过程（PDCA）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>内容</th></tr></thead><tbody><tr><td><strong>P（Plan）</strong>— 软件规格说明</td><td>规定软件功能及运行时限制</td></tr><tr><td><strong>D（Do）</strong>— 软件开发</td><td>开发满足规格说明的软件</td></tr><tr><td><strong>C（Check）</strong>— 软件确认</td><td>确认软件满足用户需求</td></tr><tr><td><strong>A（Action）</strong>— 软件演进</td><td>运行中不断改进满足新需求</td></tr></tbody></table><hr><h3 id="三、软件系统工具分类" tabindex="-1">三、软件系统工具分类 <a class="header-anchor" href="#三、软件系统工具分类" aria-label="Permalink to &quot;三、软件系统工具分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类别</th><th>包含工具</th></tr></thead><tbody><tr><td><strong>软件开发工具</strong></td><td>需求分析工具、设计工具、编码与排错工具、测试工具</td></tr><tr><td><strong>软件维护工具</strong></td><td><strong>版本控制工具</strong>、文档分析工具、开发信息库工具、逆向工程工具、再工程工具</td></tr><tr><td><strong>软件管理和软件支持工具</strong></td><td>项目管理工具、配置管理工具、<strong>软件评价工具</strong></td></tr></tbody></table><hr><h3 id="四、能力成熟度模型-cmm-★" tabindex="-1">四、能力成熟度模型 CMM ★ <a class="header-anchor" href="#四、能力成熟度模型-cmm-★" aria-label="Permalink to &quot;四、能力成熟度模型 CMM ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>特点</th><th style="text-align:center;">关键过程区域数</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>1. 初始级</strong></td><td>过程无明确定义，成败依赖个人</td><td style="text-align:center;">无</td></tr><tr><td style="text-align:center;"><strong>2. 可重复级</strong></td><td>建立基本项目管理过程，能跟踪费用/进度/功能</td><td style="text-align:center;"><strong>6 个</strong>（配置管理、质量保证、子合同管理、项目跟踪监督、项目策划、需求管理）</td></tr><tr><td style="text-align:center;"><strong>3. 已定义级</strong></td><td>过程文档化/标准化，整合为组织标准软件过程</td><td style="text-align:center;">7 个（同行评审、组间协调、产品工程、集成管理、培训大纲、过程定义、过程焦点）</td></tr><tr><td style="text-align:center;"><strong>4. 已管理级</strong></td><td>制定详细度量标准，定量理解和控制</td><td style="text-align:center;">2 个（质量管理、定量过程管理）</td></tr><tr><td style="text-align:center;"><strong>5. 优化级</strong></td><td>定量分析+过程持续改进</td><td style="text-align:center;">3 个（过程更改管理、技术改革管理、缺陷预防）</td></tr></tbody></table><h4 id="cmmi-能力成熟度模型集成" tabindex="-1">CMMI（能力成熟度模型集成） <a class="header-anchor" href="#cmmi-能力成熟度模型集成" aria-label="Permalink to &quot;CMMI（能力成熟度模型集成）&quot;">​</a></h4><blockquote><p>CMMI 是 CMM 的升级版，支持多工程学科和领域。</p></blockquote><p><strong>两种表示方法：</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>关注点</th><th>特点</th></tr></thead><tbody><tr><td><strong>阶段式模型</strong></td><td>组织整体成熟度</td><td>5 级：初始级→已管理级→已定义级→定量管理级→优化级</td></tr><tr><td><strong>连续式模型</strong></td><td>每个过程域的能力</td><td>不同过程域可达不同能力等级</td></tr></tbody></table><p><strong>CMMI 阶段式 5 级：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>特点</th></tr></thead><tbody><tr><td style="text-align:center;">1.初始级</td><td>过程不可预测且缺乏控制</td></tr><tr><td style="text-align:center;">2.已管理级</td><td>过程为项目服务（需求管理、项目计划、配置管理、度量和分析等）</td></tr><tr><td style="text-align:center;">3.已定义级</td><td>过程为组织服务（需求开发、技术解决方案、验证、确认、风险管理等）</td></tr><tr><td style="text-align:center;">4.定量管理级</td><td>过程已度量和控制（组织过程性能、定量项目管理）</td></tr><tr><td style="text-align:center;">5.优化级</td><td>集中过程改进和优化（组织级改革与实施、因果分析和解决方案）；<strong>使用从多个项目收集的数据关注组织级绩效</strong></td></tr></tbody></table><p><strong>CMMI 级别易混辨析 ★：</strong></p><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>关键识别词</th></tr></thead><tbody><tr><td style="text-align:center;">2.已管理级</td><td>过程为<strong>项目</strong>服务，能策划/执行/监督/控制项目级过程，<strong>过程已文档化</strong></td></tr><tr><td style="text-align:center;">3.已定义级</td><td>过程为<strong>组织</strong>服务，标准化过程，量身定制</td></tr><tr><td style="text-align:center;">4.量化管理级</td><td><strong>定量</strong>理解和控制，过程性能<strong>可预测</strong> — 与已定义级的核心区别</td></tr><tr><td style="text-align:center;">5.优化级</td><td><strong>持续改进</strong>，关注<strong>组织级</strong>绩效数据</td></tr></tbody></table><blockquote><p>⚠️ 易错辨析：量化管理级 vs 已定义级的关键区别是<strong>过程性能的可预测性</strong>（不是标准化程度也不是项目管理严格程度）。</p></blockquote><p><strong>CMMI 体系文件四层（自顶向下）★：</strong></p><blockquote><p>🎯 一句话结论：<strong>方针 → 过程 → 规程 → 模板</strong>（①→③→④→②）。</p></blockquote><table tabindex="0"><thead><tr><th style="text-align:center;">层次</th><th>内容</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;">1</td><td><strong>顶层方针</strong></td><td>组织质量方针和目标</td></tr><tr><td style="text-align:center;">2</td><td><strong>过程文件</strong></td><td>描述做什么、由谁做</td></tr><tr><td style="text-align:center;">3</td><td><strong>规程文件</strong></td><td>描述如何做</td></tr><tr><td style="text-align:center;">4</td><td><strong>模板类文件</strong></td><td>具体执行时的表单、检查单</td></tr></tbody></table><p><strong>CMMI 四个知识体系：</strong> 系统工程 + 软件工程 + 集成产品与过程开发 + 供应商采购</p><hr><h3 id="五、软件过程模型-★" tabindex="-1">五、软件过程模型 ★ <a class="header-anchor" href="#五、软件过程模型-★" aria-label="Permalink to &quot;五、软件过程模型 ★&quot;">​</a></h3><h4 id="核心模型对比" tabindex="-1">核心模型对比 <a class="header-anchor" href="#核心模型对比" aria-label="Permalink to &quot;核心模型对比&quot;">​</a></h4><table tabindex="0"><thead><tr><th>特性</th><th>瀑布模型</th><th>螺旋模型</th><th>原型化模型</th><th>增量模型</th><th>喷泉模型</th><th>CBSD</th><th>形式化方法</th></tr></thead><tbody><tr><td><strong>核心思想</strong></td><td>线性顺序分阶段</td><td>迭代原型+风险分析</td><td>快速原型交互理解需求</td><td>逐步开发核心和非核心</td><td>迭代无间隙，面向对象</td><td>预包装构件构造系统</td><td>严格数学基础</td></tr><tr><td><strong>适用</strong></td><td>需求明确，结构化高</td><td>庞大复杂高风险</td><td>需求不明确需快速迭代</td><td>可逐步交付的复杂系统</td><td>面向对象开发</td><td>高复用性需求</td><td>高可靠性系统</td></tr><tr><td><strong>用户参与</strong></td><td>低</td><td>高</td><td>高</td><td>高</td><td>高</td><td>中</td><td>低</td></tr><tr><td><strong>风险控制</strong></td><td>中</td><td>高</td><td>中</td><td>中</td><td>中</td><td>中</td><td>高</td></tr><tr><td><strong>复用性</strong></td><td>低</td><td>中</td><td>中</td><td>中</td><td>中</td><td>高</td><td>低</td></tr></tbody></table><h4 id="各模型详解" tabindex="-1">各模型详解 <a class="header-anchor" href="#各模型详解" aria-label="Permalink to &quot;各模型详解&quot;">​</a></h4><p><strong>1. 瀑布模型 ★</strong></p><blockquote><p>结构化开发方法的标准模型，前阶段输出 = 后阶段输入，每个阶段结束有里程碑。</p></blockquote><p>阶段：可行性分析 → 需求分析 → 软件设计 → 编码（含单元测试）→ 测试 → 运行维护。</p><ul><li>优点：概念清晰、易于理解、进度好控制</li><li>缺点：需求难一次确定、变更代价高、各阶段不能并行</li><li><strong>阶段数量：6 个</strong>（可行性分析 → 需求分析 → 软件设计 → 编码 → 测试 → 运行维护）</li><li>关键记忆：<strong>功能清晰、需求明确 → 选瀑布模型</strong></li></ul><blockquote><p>⚠️ 常见坑：「瀑布模型可以有效避免风险」— 错！瀑布模型的缺点恰恰是需求变更代价高、<strong>不能有效避免风险</strong>（风险控制的正确答案是螺旋模型）。</p></blockquote><blockquote><p>⚠️ 常见坑：「每个阶段都能完全解决所有问题，不会出现遗漏或错误」— 错！前阶段的错误和疏漏会隐蔽地带到后阶段。</p></blockquote><p><strong>2. 原型模型</strong></p><blockquote><p>解决瀑布模型需求难以一次确定的缺点。</p></blockquote><p>两个阶段：<strong>原型开发 → 目标软件开发</strong>。</p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>抛弃型原型</strong></td><td>原型仅用于需求确认，确认后抛弃，继续用瀑布模型</td></tr><tr><td><strong>演化型原型</strong></td><td>不断补充完善原型，直至形成完整产品</td></tr></tbody></table><ul><li>特点：对用户需求<strong>动态响应、逐步纳入</strong>，构造方便快速造价低</li><li>原型化模型主要目的：<strong>通过迭代获取用户满意的系统</strong></li><li>原型分类（按最终结果）：<strong>抛弃型原型</strong>和<strong>演化型原型</strong></li><li>抛弃型原型的主要作用：<strong>需求确认后被抛弃</strong>，确认后继续用瀑布模型</li></ul><p><strong>3. 增量模型</strong></p><blockquote><p>首先开发核心模块，优先级最高的服务最先交付。</p></blockquote><ul><li>优点：逐步确认降低风险</li><li>缺点：不利于模块划分（非整体规划）</li><li>与原型区别：增量模型每次版本都是<strong>独立可操作的作品</strong>，原型构造一般是为了演示</li></ul><blockquote><p>🎯 <strong>迭代 vs 增量辨析 ★</strong>: 迭代 = 重复开发过程（精化已有功能），增量 = 逐步添加功能。两者概念不同但常结合使用（如 RUP 增量迭代）。一个增量可以包含多次迭代。</p></blockquote><p><strong>4. 螺旋模型 ★</strong></p><blockquote><p>演化软件过程模型，<strong>风险驱动</strong>，适用于<strong>庞大复杂高风险系统</strong>。</p></blockquote><p>四个象限：<strong>制定计划 → 风险分析 → 实施工程 → 客户评估</strong>。</p><ul><li>两个显著特点：① 采用<strong>循环</strong>方式逐步加深系统定义和实现深度，降低风险；② 确定一系列<strong>里程碑</strong>，确保利益相关者都支持</li><li>本质：<strong>瀑布模型 + 快速原型模型</strong>的结合体，强调<strong>风险分析</strong></li><li>包含维护周期，维护和开发之间没有本质区别</li><li>适用于：面向规格说明、面向过程、面向对象的软件开发方法<strong>均可</strong></li></ul><blockquote><p>⚠️ 常见坑：「螺旋模型仅适用于面向对象开发」— 错！螺旋模型适用于<strong>多种开发方法和组合</strong>。</p></blockquote><p><strong>V模型 ★：</strong></p><blockquote><p>🎯 一句话结论：V模型最突出的特点是<strong>测试贯穿始终</strong>，左半部分验证右半部分的对应阶段。</p></blockquote><p><strong>RAD 快速应用开发 ★：</strong></p><blockquote><p>🎯 一句话结论：RAD 是基于<strong>构件</strong>的增量型开发方法，强调<strong>极短的开发周期</strong>，模块化程度要求高。</p></blockquote><p><strong>RAD 流程（5步，按顺序）：</strong></p><ol><li><strong>业务建模</strong> — 信息流建模（最先）</li><li><strong>数据建模</strong> — 将信息流精化为数据对象</li><li><strong>过程建模</strong> — 数据对象的增删改查处理</li><li><strong>应用生成</strong> — 自动化工具 + 构件组装</li><li><strong>测试与交付</strong> — 测试新构件和接口</li></ol><p><strong>RAD 适用条件：</strong> 系统<strong>模块化程度高</strong> | 不适用：新技术多、系统互操作性强、用户参与不足</p><p><strong>5. 敏捷方法</strong></p><blockquote><p>开发宣言：<strong>个体和交互 &gt; 过程和工具；可工作的软件 &gt; 面面俱到的文档；客户合作 &gt; 合同谈判；响应变化 &gt; 遵循计划</strong>。</p></blockquote><p>两个核心特点：<strong>&quot;适应性&quot;</strong> 而非预设性；<strong>&quot;面向人&quot;</strong> 而非面向过程。</p><table tabindex="0"><thead><tr><th>方法</th><th>核心理念</th><th>关键实践</th></tr></thead><tbody><tr><td><strong>极限编程（XP）</strong></td><td>交流、朴素、反馈、勇气</td><td><strong>测试先行</strong>，近螺旋式开发，小周期迭代</td></tr><tr><td><strong>水晶系列</strong></td><td>以人为中心</td><td>机动性方法，共性核心元素</td></tr><tr><td><strong>并列争球法（Scrum）</strong></td><td>迭代增量化过程</td><td>**冲刺（Sprint）**约 30 天/次，<strong>固定周期 + 三个核心角色（Scrum主管/产品负责人/开发团队）+ 每日站会</strong>；<strong>产品 Backlog</strong> 管理产品需求列表，<strong>Sprint Backlog</strong> 管理冲刺任务</td></tr><tr><td><strong>特性驱动（FDD）</strong></td><td>人+过程+技术</td><td>5 核心过程：整体对象模型→特征列表→计划→设计→构建；<strong>开发人员分为首席程序员和&quot;类&quot;程序员</strong></td></tr><tr><td><strong>动态系统开发（DSDM）</strong></td><td><strong>以业务为核心</strong></td><td>强调业务需求驱动，固定时间和资源下最大化功能交付</td></tr><tr><td><strong>开源开发方法</strong></td><td>地域分布广的团队</td><td>适用于<strong>程序开发人员地域分布很广</strong>的开发团队，&quot;眼睛越多错误越少&quot;</td></tr></tbody></table><p><strong>6. 统一过程模型（RUP）</strong></p><blockquote><p>重量级过程模型，用例驱动、以架构为中心、迭代和增量。</p></blockquote><p><strong>4 个阶段：</strong> 初始 → 细化 → 构造 → 移交。</p><p><strong>9 个核心工作流：</strong> 业务建模、需求、分析与设计、实现、测试、部署、配置与变更管理、项目管理、环境。</p><p><strong>4+1 视图模型：</strong> 用例视图（场景）→ 逻辑视图（功能/类图）→ 实现视图（模块组织/包图组件图）→ 进程视图（并发性能/活动图）→ 部署视图（拓扑结构/部署图）。</p><p><strong>7. 其他模型</strong></p><table tabindex="0"><thead><tr><th>模型</th><th>特点</th></tr></thead><tbody><tr><td><strong>喷泉模型</strong></td><td>以用户需求为动力、对象为驱动，适合面向对象开发，迭代性和无间隙性</td></tr><tr><td><strong>CBSD</strong>（基于构件开发）</td><td>利用预先包装构件构造系统，增强复用性，建立构件库</td></tr><tr><td><strong>形式化方法模型</strong></td><td>严格数学基础，生成形式化数学规格说明</td></tr></tbody></table><hr><h3 id="六、净室软件工程" tabindex="-1">六、净室软件工程 <a class="header-anchor" href="#六、净室软件工程" aria-label="Permalink to &quot;六、净室软件工程&quot;">​</a></h3><blockquote><p>以数学和统计学为基础，强调<strong>从源头预防缺陷</strong>，而非先开发再测试修复。</p></blockquote><p><strong>核心理念：</strong> 预防胜于修复、统计质量控制、零缺陷开发。</p><p><strong>应用技术：</strong> 统计过程控制（增量开发中监控质量）、基于函数的规范与设计、正确性验证（编码前验证）、统计测试和软件认证。</p><p><strong>缺点：</strong> 理论化（需数学知识）、耗时（正确性验证困难）、不进行传统模块测试可能不现实。</p>',81)])])}const p=r(e,[["render",s]]);export{c as __pageData,p as default};
